from collections import defaultdict
from typing import List

class Solution:
    def findItinerary(self, tickets: List[List[str]]) -> List[str]:
        adj = defaultdict(list)
        for u, v in sorted(tickets, reverse=True):
            adj[u].append(v)

        route = []
        def dfs(airport: str):
            while adj[airport]:
                nxt = adj[airport].pop()
                dfs(nxt)
            route.append(airport)

        dfs("JFK")
        return route[::-1]

class Solution {
public:
    vector<string> findItinerary(vector<vector<string>>& tickets) {
        unordered_map<string, priority_queue<string, vector<string>, greater<string>>> adj;
        for (const auto& t : tickets) {
            adj[t[0]].push(t[1]);
        }
        vector<string> route;
        function<void(string)> dfs = [&](string airport) {
            while (!adj[airport].empty()) {
                string nxt = adj[airport].top();
                adj[airport].pop();
                dfs(nxt);
            }
            route.push_back(airport);
        };
        dfs("JFK");
        reverse(route.begin(), route.end());
        return route;
    }
};

class Solution {
    public List<String> findItinerary(List<List<String>> tickets) {
        Map<String, PriorityQueue<String>> adj = new HashMap<>();
        for (List<String> t : tickets) {
            adj.computeIfAbsent(t.get(0), k -> new PriorityQueue<>()).offer(t.get(1));
        }
        List<String> route = new LinkedList<>();
        dfs("JFK", adj, route);
        return route;
    }
    private void dfs(String airport, Map<String, PriorityQueue<String>> adj, List<String> route) {
        PriorityQueue<String> pq = adj.get(airport);
        while (pq != null && !pq.isEmpty()) {
            dfs(pq.poll(), adj, route);
        }
        route.add(0, airport);
    }
}

